//! 🧪️ General checkpoint facts donate original authored metadata while copying parent identities in bounded turns.
use super::*;
use crate::{Author,Checkpoint};
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn observe<T>(run:impl FnOnce()->T)->(T,usize,usize){semio_framework_trace_memory_testing::observe_backing(run)}
#[test]
fn original_commit_facts_preserve_authored_allocations_and_every_cancelled_prefix(){
 let law:serde_json::Value=serde_json::from_str(include_str!("commit-facts.json")).unwrap();
 for cut in law["cancelCuts"].as_array().unwrap().iter().map(|value|Some(value.as_u64().unwrap()as usize)).chain([None]){
  let parent=Checkpoint{id:law["parent"]["id"].as_str().unwrap().into(),change_ids:vec!["change-old".into(),"change-other".into()],parent_id:None,authors:Vec::new(),message:None,timestamp:"parent-time".into(),composition_pins:Vec::new()};
  let input=OriginalCommitFactInput{generation:71,parent:Some(&parent),change_id:law["changeId"].as_str().unwrap(),saved_at:law["savedAt"].as_str().unwrap(),timestamp:law["timestamp"].as_str().unwrap()};
  let mut pending=Some(vec!["edit-new".into(),"edit-next".into()]);let pending_ptr=pending.as_ref().unwrap().as_ptr();let mut message=Some(law["message"].as_str().unwrap().to_owned());let message_ptr=message.as_ref().unwrap().as_ptr();let mut authors=vec![Author{id:"author-energy".into(),name:"Energy Author".into(),avatar:Some("energy-avatar".into())}];let authors_ptr=authors.as_ptr();let mut owner=OriginalCommitFactBirth::default();
  for step in 0..100000{if cut==Some(step)||owner.ready(){break}let d=owner.demands(&input).unwrap();let exact=grant(d);for axis in 0..5{let mut denied=exact;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue};let(p,born,freed)=observe(||owner.advance(&input,&mut pending,&mut message,&mut authors,denied).unwrap());assert_eq!(p,Default::default());assert_eq!((born,freed),(0,0));assert_eq!(owner.demands(&input).unwrap(),d);}let(p,born,freed)=observe(||owner.advance(&input,&mut pending,&mut message,&mut authors,exact).unwrap());assert_eq!((p.retained_capacity_bytes,p.released_bytes),(born,freed));assert!(p.fits(exact));assert!(step<99999);}
  if cut.is_none(){assert!(owner.ready());let d=OriginalCommitFactBirth::take_demands();let((change,checkpoint),p)=owner.take(grant(d)).unwrap().unwrap();assert!(p.fits(grant(d)));assert_eq!(change.edit_ids.as_ptr(),pending_ptr);assert_eq!(checkpoint.message.as_ref().unwrap().as_ptr(),message_ptr);assert_eq!(checkpoint.authors.as_ptr(),authors_ptr);assert_eq!(serde_json::to_value(&change).unwrap(),law["expected"]["change"]);assert_eq!(serde_json::from_str::<serde_json::Value>(&semio_framework_pack_json::to_json_string(&checkpoint)).unwrap(),law["expected"]["checkpoint"]);let mut close=semio_framework_value::retained_clone::RetainedCloneClose::default();let mut original=Some((change,checkpoint));let d=close.next_owner_demands::<(crate::Change,Checkpoint)>(true,&None,4096).unwrap();close.begin_granted(&mut original,grant(d)).unwrap();while !close.is_empty(){let d=close.demands(4096).unwrap();let(p,born,freed)=observe(||close.step_granted(grant(d)).unwrap().progress());assert_eq!((p.retained_capacity_bytes,p.released_bytes),(born,freed));}}
  for step in 0..100000{if owner.terminal_is_empty(){break}let d=owner.close_demands(4096).unwrap();let g=grant(d);for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue};let(p,born,freed)=observe(||owner.close_step(denied).unwrap().progress());assert_eq!(p,Default::default());assert_eq!((born,freed),(0,0));assert_eq!(owner.close_demands(4096).unwrap(),d);}let(p,born,freed)=observe(||owner.close_step(g).unwrap().progress());assert_eq!((p.retained_capacity_bytes,p.released_bytes),(born,freed));assert!(step<99999);}
  assert!(owner.terminal_is_empty());let(_,born,freed)=observe(||drop(owner));assert_eq!((born,freed),(0,0));
 }
}
